source "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"

_choice_command() {
    if [[ "$ARGC_CWORD" != \\* ]]; then
        return 0
    fi
    psql --help=commands 2>/dev/null | gawk '
        function flush() {
            if (name != "") {
                if (desc != "") {
                    printf "%s\t%s\n", name, desc
                } else {
                    print name
                }
            }
            name = ""
            desc = ""
        }
        /^  \\/ {
            flush()
            line = $0
            sub(/^  /, "", line)
            if (match(line, /^\\[A-Za-z?!][A-Za-z0-9_?!]*/)) {
                name = substr(line, RSTART, RLENGTH)
                rest = substr(line, RLENGTH + 1)
                sub(/^[[:space:]]+/, "", rest)
                if (rest ~ /^\[/ || rest ~ /^</) {
                    rest = ""
                }
                desc = rest
            }
            next
        }
        END { flush() }
    '
}

_choice_dbname() {
    _argc_util_cache 300 _choice_dbname_uncached "psql_dbname:${argc_host:-}:${argc_port:-}:${argc_username:-}"
}

_choice_dbname_uncached() {
    local args=(-X -w -A -t -d postgres)
    [[ -n "${argc_host:-}" ]] && args+=(-h "$argc_host")
    [[ -n "${argc_port:-}" ]] && args+=(-p "$argc_port")
    [[ -n "${argc_username:-}" ]] && args+=(-U "$argc_username")
    PGCONNECT_TIMEOUT=1 psql "${args[@]}" -c 'select datname from pg_database where datallowconn order by 1' 2>/dev/null
}

_choice_pset() {
    cat <<-'EOF' | _argc_util_comp_kv =
	border=;;number of columns per border line
	columns=;;number of columns
	csv=on,off;;toggle CSV output mode
	expanded=on,off,auto;;toggle expanded output
	fieldsep=;;field separator for unaligned output
	fieldsep_zero=;;zero-byte field separator
	footer=on,off;;show table footer
	format=aligned,unaligned,wrapped,html,asciidoc,latex,latex-longtable,troff-ms,csv;;output format
	linestyle=ascii,old-ascii,unicode;;border line style
	null=;;string printed for null values
	numericlocale=on,off;;locale-aware numeric formatting
	pager=on,off,always;;pager usage
	pager_min_lines=;;minimum lines before the pager is used
	recordsep=;;record separator for unaligned output
	recordsep_zero=;;zero-byte record separator
	tableattr=;;attributes for the HTML table tag
	title=;;table title
	tuples_only=on,off;;show only tuples
	EOF
}

_choice_username() {
    _argc_util_cache 300 _choice_username_uncached "psql_username:${argc_host:-}:${argc_port:-}"
}

_choice_username_uncached() {
    local args=(-X -w -A -t -d postgres)
    [[ -n "${argc_host:-}" ]] && args+=(-h "$argc_host")
    [[ -n "${argc_port:-}" ]] && args+=(-p "$argc_port")
    PGCONNECT_TIMEOUT=1 psql "${args[@]}" -c 'select rolname from pg_roles where rolcanlogin order by 1' 2>/dev/null
}

_choice_variable() {
    _argc_util_mode_kv =
    if [[ -n "$argc__kv_prefix" ]]; then
        return 0
    fi
    psql --help=variables 2>/dev/null | gawk '
        function flush() {
            if (name != "") {
                if (desc != "") {
                    printf "%s\t%s\n", name, desc
                } else {
                    print name
                }
            }
            name = ""
            desc = ""
        }
        /^  [A-Z][A-Z0-9_]*$/ {
            flush()
            name = $0
            sub(/^[[:space:]]+/, "", name)
            next
        }
        name != "" && desc == "" && /^    [^[:space:]]/ {
            desc = $0
            sub(/^[[:space:]]+/, "", desc)
            next
        }
        { if ($0 !~ /^    /) flush() }
        END { flush() }
    ' | _argc_util_transform suffix== nospace
}
